func txTimestamp(ctx contractapi.TransactionContextInterface) (int64, error) {
	ts, err := ctx.GetStub().GetTxTimestamp()
	if err != nil {
		return 0, fmt.Errorf("GetTxTimestamp: %w", err)
	}
	return ts.AsTime().Unix(), nil
}

func emitAdvisory(ctx contractapi.TransactionContextInterface, def, detail string) {
	payload := []byte(fmt.Sprintf(`{"def":%q,"violation":%q}`, def, detail))
	_ = ctx.GetStub().SetEvent("TemporalViolation", payload)
}

// emitCrossChainTrigger announces a Level-3 (cross-blockchain) constraint
// touchpoint, regardless of whether this call is the send or the receive
// side of the interaction -- generic, unlike a hand-written trigger such as
// pharma_manufacturer.go's ad hoc SetEvent("BatchReleaseAnchored", ...).
func emitCrossChainTrigger(ctx contractapi.TransactionContextInterface, def, processID, msgID string, tau int64) {
	payload := []byte(fmt.Sprintf(`{"def":%q,"processId":%q,"msgId":%q,"tau":%d}`, def, processID, msgID, tau))
	_ = ctx.GetStub().SetEvent("CrossBlockchainInteractionTriggered", payload)
}

func flowKey(processID, taskID string) string {
	return fmt.Sprintf("flow_%s_%s", processID, taskID)
}

func hasTaskExecuted(ctx contractapi.TransactionContextInterface, processID, taskID string) (bool, error) {
	data, err := ctx.GetStub().GetState(flowKey(processID, taskID))
	if err != nil || data == nil {
		return false, err
	}
	var fs FlowState
	if err := json.Unmarshal(data, &fs); err != nil {
		return false, err
	}
	return fs.Executed, nil
}

func recordTaskExecuted(ctx contractapi.TransactionContextInterface, processID, taskID string, now int64) error {
	data, err := json.Marshal(FlowState{Executed: true, Time: now})
	if err != nil {
		return err
	}
	return ctx.GetStub().PutState(flowKey(processID, taskID), data)
}

func xorChoiceKey(processID, gatewayID string) string {
	return fmt.Sprintf("xorchoice_%s_%s", processID, gatewayID)
}

func claimXorChoice(ctx contractapi.TransactionContextInterface, processID, gatewayID, taskID string) error {
	key := xorChoiceKey(processID, gatewayID)
	existing, err := ctx.GetStub().GetState(key)
	if err != nil {
		return err
	}
	if existing != nil {
		return fmt.Errorf("GATEWAY-XOR-CLAIM: XOR split %s already claimed by %s, task %s cannot execute process=%s",
			gatewayID, string(existing), taskID, processID)
	}
	return ctx.GetStub().PutState(key, []byte(taskID))
}

func checkXorChoice(ctx contractapi.TransactionContextInterface, processID, gatewayID, taskID string) error {
	key := xorChoiceKey(processID, gatewayID)
	existing, err := ctx.GetStub().GetState(key)
	if err != nil {
		return err
	}
	if existing == nil {
		return fmt.Errorf("GATEWAY-XOR-NOT-RESOLVED: XOR split %s not yet resolved, task %s cannot execute process=%s",
			gatewayID, taskID, processID)
	}
	if string(existing) != taskID {
		return fmt.Errorf("GATEWAY-XOR-REJECTED: XOR split %s resolved to %s, task %s cannot execute process=%s",
			gatewayID, string(existing), taskID, processID)
	}
	return nil
}

// resolveXorChoice is called exactly once, by the resolver task's own
// invocation — its self-firing guard (hasTaskExecuted, first statement in
// every Execute_*) already guarantees at most one call per process instance,
// so this writes unconditionally: there is no concurrent writer to arbitrate,
// unlike claimXorChoice's race between independently-invoked sibling branches.
func resolveXorChoice(ctx contractapi.TransactionContextInterface, processID, gatewayID, taskID string) error {
	return ctx.GetStub().PutState(xorChoiceKey(processID, gatewayID), []byte(taskID))
}

