// ── Validation du lot par le Regulateur
func (cc *pharma_interorg_inverted_RegulateurChaincode) Execute_ValidateLot(ctx contractapi.TransactionContextInterface, processID string, availMsgId string) error {
	// GATEWAY-REFIRE Timer Guard (blocking): a task instance may execute
	// at most once per processID — Caterpillar's marking bit is single-use
	// (Table 4.1 "All patterns": deactivates itself on execution).
	if already, err := hasTaskExecuted(ctx, processID, "Task_ValidateLot"); err != nil {
		return err
	} else if already {
		return fmt.Errorf("GATEWAY-REFIRE: task %s already executed for process %s", "Task_ValidateLot", processID)
	}

	now, err := txTimestamp(ctx)
	if err != nil {
		return err
	}

	emitCrossChainTrigger(ctx, "CBTD", processID, availMsgId, now)

	// CBTD-9 (FS) Timer Guard: check cross-blockchain temporal dependency (advisory)
	cbtdAKey := fmt.Sprintf("cbtd_a_%s_FS", processID)
	if cbtdBytes, err := ctx.GetStub().GetState(cbtdAKey); err == nil && cbtdBytes != nil {
		var cbtdA CBTDState
		json.Unmarshal(cbtdBytes, &cbtdA)
		gap := now - cbtdA.Tau
		if gap < 0 { gap = -gap }
		if gap < 600 || gap > 900 {
			emitAdvisory(ctx, "CBTD-9", fmt.Sprintf("FS gap=%d [600,900] process=%s", gap, processID))
		}
		cbtdBData, _ := json.Marshal(map[string]interface{}{"msgId": availMsgId, "tau": now, "gap": gap})
		ctx.GetStub().PutState(fmt.Sprintf("cbtd_b_%s_FS", processID), cbtdBData)
	}

	// GATEWAY: record this task's own completion for downstream precedence checks
	if err := recordTaskExecuted(ctx, processID, "Task_ValidateLot", now); err != nil {
		return err
	}

	return nil
}

